async function injectV7Bridge() {
  const code = `(function(){
    if(window.__V7_BRIDGE__) return;
    window.__V7_BRIDGE__ = true;

    window.addEventListener('message', async function sznV7Handler(event) {
      const msg = event.data;
      if (!msg || msg.type !== 'SZN_V7_RUN') return;

      const { reqId, ab, fileName, fileType } = msg;

      function reply(ok, error) {
        event.source.postMessage({ type: 'SZN_V7_RESULT', reqId, ok, error }, '*');
      }

      try {
        const POLL_MS = 100, MAX_WAIT = 15000;
        let waited = 0;
        while (typeof V7Patch !== 'function') {
          if (waited >= MAX_WAIT) {
            reply(false, 'V7Patch timeout ' + MAX_WAIT + 'ms');
            return;
          }
          await new Promise(r => setTimeout(r, POLL_MS));
          waited += POLL_MS;
        }

        const file = new File([ab], fileName, { type: fileType });
        const patchResult = await V7Patch(file);

        let patchedFile;
        if (patchResult instanceof File) {
          patchedFile = new File([patchResult], fileName, { type: fileType });
        } else if (patchResult instanceof Blob || patchResult instanceof ArrayBuffer || ArrayBuffer.isView(patchResult)) {
          patchedFile = new File([patchResult], fileName, { type: fileType });
        } else if (patchResult === null || patchResult === undefined) {
          reply(false, 'V7Patch return error (null/undefined) — Patch not approved');
          return;
        } else {
          reply(false, 'V7Patch return undefined: ' + Object.prototype.toString.call(patchResult));
          return;
        }

        const sels = [
          'input[type="file"][accept="video/*"]',
          'input[type="file"][accept*="video"]',
          '[class*="hiddenInput"] input[type="file"]',
          'input[type="file"]',
        ];
        let input = null;
        for (const sel of sels) {
          const el = document.querySelector(sel);
          if (el) { input = el; break; }
        }
        if (!input) { reply(false, 'input[type=file] not found'); return; }

        const dt = new DataTransfer();
        dt.items.add(patchedFile);

        const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'files');
        if (nativeSetter && nativeSetter.set) {
          try { nativeSetter.set.call(input, dt.files); } catch(_) {}
        } else {
          try { Object.defineProperty(input, 'files', { value: dt.files, configurable: true }); } catch(_) {}
        }

        input.dispatchEvent(new Event('input',  { bubbles: true, cancelable: true }));
        input.dispatchEvent(new Event('change', { bubbles: true, cancelable: true }));

        reply(true);
      } catch(err) {
        reply(false, err && err.message ? err.message : String(err));
      }
    });
  })();`;
  await injectCodeToMainWorld(code);
}

